import os

from openai import OpenAI

# Ollama 的 OpenAI 相容端點：本機是 http://localhost:11434/v1，
# Ollama 自己的雲端是 https://ollama.com/v1（官方文件的 Base URLs 表）。
LOCAL_BASE_URL = "http://localhost:11434/v1"
CLOUD_BASE_URL = "https://ollama.com/v1"

# 只有下載到這台機器的標籤才算本機；帶 cloud 字樣的標籤會送到 Ollama 的雲端，
# 即使 base_url 指的是本機伺服器也一樣。
LOCAL_MODELS = {"gpt-oss:20b", "qwen3.6:35b", "gemma4:12b"}


def ensure_local_tag(model: str) -> None:
  """本機那一步的守門員：標籤不在白名單就不要送出去。"""
  if model not in LOCAL_MODELS:
    raise ValueError(f"{model} is not a downloaded local tag")


def get_client(target: str) -> OpenAI:
  """target 是 'local' 或 'cloud'，換的只有 base_url 和金鑰。"""
  if target == "local":
    # 本機不檢查金鑰，用戶端仍要求填一個值，官方範例填 'ollama'。
    return OpenAI(base_url=LOCAL_BASE_URL, api_key="ollama", timeout=30.0)
  if target == "cloud":
    # 雲端要求真正的金鑰，一律從環境變數讀，不寫進程式。
    return OpenAI(
      base_url=CLOUD_BASE_URL,
      api_key=os.environ["OLLAMA_API_KEY"],
      timeout=30.0,
    )
  raise ValueError(f"unknown target: {target}")


def ask(target: str, model: str, prompt: str) -> str:
  if target == "local":
    ensure_local_tag(model)
  client = get_client(target)
  response = client.chat.completions.create(
    model=model,
    messages=[{"role": "user", "content": prompt}],
  )
  return response.choices[0].message.content


if __name__ == "__main__":
  # 本機模型只留在自己的機器上執行。
  print(ask("local", "gpt-oss:20b", "用一句話說明什麼是去識別化"))
